const id = $json.body.campaign_id;
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (typeof id !== 'string' || !uuidRe.test(id)) {
  throw new Error('campaign_id missing or not a valid UUID: ' + JSON.stringify(id));
}
return [{ json: { campaign_id: id } }];

const row = $('Get campaign').item.json;
const client = $json;
if (!row || !row.id) throw new Error('Campaign row not found.');
const token = $('Get Meta credentials').item.json.system_user_token;
if (!token) throw new Error('meta_ads_settings.system_user_token is not set.');

const adAccount = (row.meta_ad_account_id || client.meta_ad_account_id || '').trim();
if (!adAccount || !/^act_\d+$/.test(adAccount)) {
  throw new Error('Campaign/client has no valid meta_ad_account_id (expected act_XXXXXXXXXX): ' + JSON.stringify(adAccount));
}

// objective -> a conservative optimization goal. The campaign launches PAUSED
// for the agency to review and tune in Ads Manager, so a safe default beats a
// clever one that might fail validation (e.g. LEAD_GENERATION needs an instant
// form, OFFSITE_CONVERSIONS needs a pixel + event).
const OPT = {
  OUTCOME_LEADS: 'LINK_CLICKS',
  OUTCOME_SALES: 'LINK_CLICKS',
  OUTCOME_TRAFFIC: 'LINK_CLICKS',
  OUTCOME_AWARENESS: 'REACH',
  OUTCOME_ENGAGEMENT: 'POST_ENGAGEMENT',
  OUTCOME_APP_PROMOTION: 'LINK_CLICKS',
};
const objective = row.objective || 'OUTCOME_LEADS';
const optimizationGoal = OPT[objective] || 'LINK_CLICKS';

const countries = Array.isArray(row.targeting_countries) && row.targeting_countries.length
  ? row.targeting_countries.map(c => String(c).toUpperCase())
  : ['US'];
const targeting = {
  geo_locations: { countries },
  age_min: row.targeting_age_min || 18,
  age_max: row.targeting_age_max || 65,
};

const budgetUsd = Number(row.daily_budget_usd || 0);
if (!(budgetUsd > 0)) throw new Error('daily_budget_usd must be > 0.');

return [{ json: {
  campaignRowId: row.id,
  adAccount,
  accessToken: token,
  apiBase: 'https://graph.facebook.com/v21.0',
  campaignName: row.campaign_name || 'New campaign',
  objective,
  optimizationGoal,
  bidStrategy: row.bid_strategy || 'LOWEST_COST_WITHOUT_CAP',
  dailyBudgetMinor: String(Math.round(budgetUsd * 100)),
  targeting: JSON.stringify(targeting),
  startTime: new Date(Date.now() + 3600000).toISOString(),
  pageId: (client.meta_page_id || '').trim() || null,
  businessName: client.business_name || client.name || 'Our business',
  websiteUrl: client.website_url || 'https://example.com',
  primaryGoalText: row.primary_goal || '',
} }];
